mapper.select:
SELECT pni.id,
       pni.uid,
       pni.news_comment,
       pni.create_time,
       pni.time_mark
FROM b_private_news_info AS pni
WHERE pni.uid = #{bo.uid}
    AND pni.reply_target_uid = #{bo.replyTargetUid}
   OR pni.uid = #{bo.replyTargetUid}
    AND pni.reply_target_uid = #{bo.uid}
ORDER BY pni.create_time

SELECT pni.id, pni.uid, pni.reply_target_uid, pni.news_comment, pni.been_read, pni.time_mark, pni.create_time FROM b_private_news_info AS pni
AND pni.uid = #{bo.uid}
AND pni.reply_target_uid = #{bo.replyTargetUid}
AND pni.news_comment like concat('%', #{bo.newsCommentLike}, '%')
ORDER BY pni.create_time DESC

select id, been_read
from b_private_news_info
where reply_target_uid = #{uid}
  and been_read = 1;

select id, create_time
from b_private_news_info
where uid = #{uuid}
    and reply_target_uid = #{replyTargetUid}
   or uid = #{replyTargetUid} and reply_target_uid = #{uuid}
order by create_time desc LIMIT 1

SELECT uid as targetUid, count(reply_target_uid) as unreadCount FROM b_private_news_info WHERE reply_target_uid = #{uid} AND been_read = 1 AND uid IN
#{item.targetUid}
GROUP BY uid
